  /* A LIST, NOT A MATCH (§87: a name is never an identifier). The register is
     offered and a person answers — the same shape as the role picker, which
     suggests before it creates. The option a row is ALREADY on is shown as it
     is, so this reads as a fact about them rather than a question every time. */
  function registerCell(clientKey, member, register) {
    var wrap = el("span", "asrow");
    wrap.appendChild(el("span", "aslab", "on this register as"));
    var sel = el("select", "fld");
    var own = el("option", null, "a row of their own");
    own.value = "";
    sel.appendChild(own);
    register.forEach(function (r) {
      var o = el("option", null, r.name + (r.email ? " · " + r.email : ""));
      o.value = r.key;
      if (r.key === member.person_key) o.selected = true;
      sel.appendChild(o);
    });
    sel.addEventListener("change", function () {
      post({ action: "setTeam", key: clientKey, email: member.email,
             seat: member.seat, personKey: sel.value })
        .then(function (r) {
          /* SAID AFTER THE REDRAW THAT REPORTS IT (§63, and I wrote it the
             wrong way round again in the same file): `settle()` replaces the
             page, so a refusal said before it is wiped a moment later and the
             control simply springs back with no explanation. */
          drawClient(clientKey, true).then(function () {
            if (!r.ok) say(r.error || "Not changed.", true);
          });
        });
    });
    wrap.appendChild(sel);
    return wrap;
  }

  function seatCell(clientKey, member, seats, editable) {
    var wrap = el("span", "cell" + (editable ? "" : " locked"));
    seats.forEach(function (s) {
      var b = el("button", null, s.name);
      b.type = "button";
      b.title = s.note;
      if (member.seat === s.key) b.className = "on" + (s.key === "super" ? " hi" : "");
      if (editable && member.seat !== s.key) {
        b.addEventListener("click", function () {
          post({ action: "setTeam", key: clientKey, email: member.email, seat: s.key })
            .then(function (r) { r.ok ? drawClient(clientKey, true)
                                      : say(r.error || "Not changed.", true); });
        });
      }
      wrap.appendChild(b);
    });
    return wrap;
  }

  /* ── Consultants ─────────────────────────────────────────────── */
